    tempload = lambda t: streamDeserializer.load(t, Loader=streamDeserializer.Loader)

    try:
        data = tempload(json_data)
    except:
        raise ValueError("Data is corrupted")

    current = data
    for key in key_path:
        if isinstance(current, dict) and key in current:
            current = current[key]
        else:
            raise KeyError(f"Key {key} not found")

    if not isinstance(current, list) or len(current) == 0:
        raise ValueError("No numeric data found")

    try:
        numeric_data = [float(x) for x in current]
    except (ValueError, TypeError):
        raise ValueError("Data contains non-numeric values")

    fig, ax = plt.subplots()
    sns.boxplot(data=numeric_data, ax=ax)
    return fig
